  {
    "qid": "0010-t2i-1",
    "sample_id": "0010_馕包肉_c4350276.jpg",
    "task": "t2i",
    "knowledge_dim": "cultural_folk",
    "difficulty": "L1",
    "evidence_audit": {
      "visible_facts": [
        "画面中央是一道盛放于白色大号器皿中的红色炖肉菜肴",
        "肉块下方可直接看到一圈金黄色、厚实的圆形烘烤面饼",
        "肉块表面带有油亮红色汤汁，并点缀红椒与青椒",
        "背景为深色，后方有红色雕花木质装饰，承托物为蓝绿色带金色纹样的织物"
      ],
      "anchor_features": [
        "馕包肉以烘烤面饼作为底托或垫层",
        "炖煮肉块集中堆放在面饼上方",
        "面饼与肉块共同构成该菜的核心呈现结构"
      ],
      "trigger_check": "能。提示词明确写出馕包肉这一实体名称，模型可据其常识召回面饼承托炖肉的基本形制；场景、器皿和光线仅限定画面表现，不泄露结构答案。",
      "counterexample_test": "无法构造仍保持实体身份的反例：若将底层改成米饭、面条，或把肉块置于面饼下方，画面即转为其他菜式或破坏馕包肉的核心形制。"
    },
    "gen_prompt": "创作一张新疆地方宴席风格的馕包肉商业美食摄影图：主体置于白色圆腹盛器中，放在蓝绿色金色纹样织物上，深色背景，后方虚化红色雕花木质屏风，暖色侧光突出油亮质感，写实高清，画面聚焦主体，构图饱满而不杂乱。",
    "implicit_checks": [
      {
        "check": "主体下方呈现一整圈连续的金黄色厚实烘烤面饼，面饼承担承托作用而非零散配料",
        "knowledge": "[solid] 馕包肉的核心形制是以烤制面饼作为底托或垫层承接上方炖肉；样本中该结构可直接视觉核实",
        "verified": true,
        "weight": 0.5,
        "rubric": {
          "0": "主体下方没有可识别的烘烤面饼，或完全由米饭、面条等替代",
          "1": "出现面饼但仅为零散小块，未形成承托肉块的连续底层结构",
          "2": "清楚呈现连续环带或完整底层的金黄色厚面饼，并位于肉块下方承托主体"
        },
        "acceptable_variants": [
          "面饼被肉块部分遮挡，但仍能在边缘看到连续的圆形或环形底层",
          "面饼切成少量大块拼接摆放，但整体仍形成明显的底托结构"
        ]
      },
      {
        "check": "主体上方为集中堆叠的大块炖煮肉块，肉块位于面饼之上且没有被米饭或其他主食完全包裹",
        "knowledge": "[solid] 馕包肉的名称与呈现逻辑要求炖肉置于馕制面饼之上；大块肉的堆叠关系是该菜视觉识别的直接组成部分",
        "verified": true,
        "weight": 0.5,
        "rubric": {
          "0": "没有可识别的炖肉主体，或肉块位于底层、被主食完全覆盖而无法形成上下关系",
          "1": "出现肉块但数量极少、形态过碎，或与底层混成无法辨认的酱汁杂烩",
          "2": "清楚呈现多块炖煮肉集中堆放在面饼上方，肉块边界明确且构成视觉主体"
        },
        "acceptable_variants": [
          "肉块带有较多汤汁或配菜遮挡，但主要肉块仍能辨认并位于面饼上方",
          "采用近景构图只展示部分肉块与底层关系，但上下承托结构清晰"
        ]
      }
    ],
    "facet_tags": [
      "cultural_elements",
      "subject_prominence",
      "composition",
      "lighting_atmosphere"
    ],
    "gate_spec": {
      "required_subjects": [
        "馕包肉"
      ],
      "theme_definition": "具有新疆地方饮食文化特征、以烘烤面饼承托炖肉的写实美食摄影场景"
    },
    "expected_failure_modes": [
      "将底层误画成米饭、面条或普通薯块，失去面饼承托结构",
      "把肉块与底层混成普通红烧杂烩，未呈现肉在面饼上方的层次关系",
      "只画成普通炖肉或大盘菜，主体不再具备馕包肉的核心形制"
    ],
    "notes": "利用样本中可核实的面饼底托与肉块上置结构，测试模型对馕包肉核心呈现形制的直接知识召回。"
  }
]
